function exerciseQuestions(spec){return spec.reading?[...spec.questions,...spec.reading.flatMap(id=>window.READING.find(t=>t.id===id).questions)]:spec.questions;}
function exerciseScore(spec,a){const qs=exerciseQuestions(spec);return {score:qs.reduce((s,q,i)=>s+Number(q.options?norm(a.answers[i])===norm(q.key):q.accept.some(x=>norm(x)===norm(a.answers[i]))),0),total:qs.length,entered:qs.filter((q,i)=>a.answers[i]?.trim()).length};}
function exerciseRoute(kind,id){const list=kind==='reading'?window.READING:window.MOCKS,spec=list.find(s=>s.id===id);if(spec){exercisePage(kind,spec);return;}
 const isMock=kind==='mock';shell(head(isMock?'Кешенді жазбаша нұсқалар':'Оқылым шеберханасы',isMock?'Үш оқу нұсқасы: 20 Use of English + 20 Reading + бір Writing.':'Алдымен мәтінді шолып оқы, содан кейін сұраққа дәлел ізде.')+`<div class="banner">${isMock?'Бұл нұсқалар жазбаша дағдыларды біріктіреді. Listening мен Speaking кірмейді; толық ресми олимпиада форматы және ресми балл шкаласы емес. Reading кітапханасындағы мәтіндер қолданылады, бұрын ашылғаны есепте белгіленеді.':'Skimming — жалпы ой; scanning — дерек іздеу; inference — мәтінге сүйеніп қорытынды; vocabulary — контекст; purpose — автор мақсаты. Кілт жауаптарды жібергеннен кейін ашылады.'}</div><div class="topics-grid">${list.map(t=>{const a=state.exercises[t.id],r=a?.submitted?exerciseScore(t,a):null;return `<a class="topic-card" href="#/${isMock?'mocks':'reading'}/${t.id}"><h2>${esc(t.title)}</h2><p>${isMock?t.minutes+' минут · 40 автоматты тармақ':esc(t.level)+' · '+countWords(t.text)+' сөз · 10 сұрақ'}</p>${pill(r?r.score+'/'+r.total:a?'Орындалып жатыр':'Жаңа',r?'good':'neutral')}<div class="topic-bottom"><span>${a?'Ашу':'Бастау'}</span>${ic('arrow')}</div></a>`;}).join('')}</div>`+(isMock?'<p class="note">Күрделілік — авторлық әдістемелік баға. Нақты олимпиаданың кезеңі мен ресми талаптары басым.</p>':''),isMock?'Нұсқалар':'Оқылым');
}
function exerciseQuestion(q,i,a,id){const value=a.answers[i]||'',submitted=a.submitted;return `<section class="question"><div class="section-mark">${i+1}. ${esc(q.skill||'Тілді қолдану')}</div><p lang="en" id="ex-label-${i}">${esc(q.q)}</p>${q.options?`<div class="options" role="group" aria-labelledby="ex-label-${i}">${q.options.map((o,j)=>`<label class="option"><input type="radio" name="ex-${id}-${i}" data-exercise="${id}" data-index="${i}" value="${'ABCD'[j]}" ${value==='ABCD'[j]?'checked':''} ${submitted?'disabled':''}><span lang="en">${'ABCD'[j]}. ${esc(o)}</span></label>`).join('')}</div>`:`<input class="answer-input" data-exercise="${id}" data-index="${i}" value="${esc(value)}" aria-labelledby="ex-label-${i}" maxlength="2000" autocomplete="off" spellcheck="false" ${submitted?'disabled':''}>`}${submitted?`<div class="feedback ${(q.options?norm(value)===norm(q.key):q.accept.some(x=>norm(x)===norm(value)))?'':'wrong'}">Сенің жауабың: ${esc(value||'—')}<br>Жауап: ${esc(q.options?q.key+' — '+q.options['ABCD'.indexOf(q.key)]:q.answer)}<br>${esc(q.explanation)}</div>`:''}</section>`;}
function exercisePage(kind,spec){const a=state.exercises[spec.id],isMock=kind==='mock',route=isMock?'mocks':'reading';
 if(!a){shell(head(spec.title,isMock?'Уақытпен жазбаша жаттығу':'Мәтінмен жұмыс',link('/'+route,'Тізімге','btn light small','back'))+`<section class="card"><p>${isMock?spec.minutes+' минут. Таймер барлық өткен уақытты, соның ішінде қойындыдағы үзілісті де есептейді. Writing мұғалімге бөлек жіберіледі.':'Мәтін мен 10 сұрақ ашылады. Барлық жауапты жібергеннен кейін түсіндірме көрінеді.'}</p>${isMock?'<p>Мәтіндерді бұрын оқыған болсаң, бұл дербес жаңа сынақ нәтижесі емес. Қайталау белгісі есепке кіреді.</p>':''}<button class="btn" data-action="start-exercise" data-kind="${kind}" data-id="${spec.id}">Бастау</button></section>`,isMock?'Нұсқалар':'Оқылым');return;}
 const result=exerciseScore(spec,a),qs=exerciseQuestions(spec),texts=isMock?spec.reading.map(id=>window.READING.find(t=>t.id===id)):[spec];
 let body=`<section class="card"><h2>${a.submitted?'Нәтиже: '+result.score+'/'+result.total:'Өз бетіңше орында'}</h2><p>${result.entered}/${result.total} жауап · ${a.submitted?(result.entered===result.total?'қысқа жауаптар жиналды':'толық емес нәтиже'):'кілт әлі жабық'}.</p><p>${isMock?'Барлық өткен уақыт':'Өткен уақыт'}: <strong id="exercise-time">${a.started===null?'Тіркелмеген':formatTime(((a.finished||Date.now())-a.started)/1000)}</strong>${isMock?' / '+spec.minutes+' минут':''}.</p>${isMock?`<p>${a.exposed.length?'Бұрын ашылған мәтіндер: '+a.exposed.join(', ')+'. Қайталау нәтижесі ретінде қара.':'Нұсқа басталғанда осы браузерде мәтіндердің бұрын ашылғаны тіркелмеген.'}</p>`:''}<p class="note">Нәтиже бастапқы диагностикаға және тақырыптың меңгерілу балдарына қосылмайды. Мәтіндер осы тренажер үшін жазылған; сипатталған оқиғалар нақты зерттеу дерегі ретінде ұсынылмайды.</p></section>`;
 let offset=0;if(isMock){body+='<h2 class="spaced">Тілді қолдану · 20 тармақ</h2>'+spec.questions.map((q,i)=>exerciseQuestion(q,i,a,spec.id)).join('');offset=spec.questions.length;}
 for(const text of texts){body+=`<section class="card text-card spaced"><h2>${esc(text.title)}</h2><div class="reading-text" lang="en">${text.text.split('\n\n').map(p=>`<p>${esc(p)}</p>`).join('')}</div></section>`+text.questions.map((q,i)=>exerciseQuestion(q,offset+i,a,spec.id)).join('');offset+=text.questions.length;}
 if(isMock){const w=spec.writing;body+=`<section class="card text-card spaced"><h2>Жазылым · ${esc(labelKk(w.title))} · ${esc(w.words)} сөз</h2><p>${esc(w.prompt)}</p>${w.facts?`<ul>${w.facts.map(f=>`<li>${esc(f)}</li>`).join('')}</ul>`:''}<label for="ex-plan">Жоспар</label><textarea id="ex-plan" class="writing-area plan-area" data-exercise-write="${spec.id}" data-field="plan" maxlength="4000" ${a.submitted?'readonly':''}>${esc(a.plan||'')}</textarea><label for="ex-text">Өз мәтінің</label><textarea id="ex-text" class="writing-area" data-exercise-write="${spec.id}" data-field="text" maxlength="20000" ${a.submitted?'readonly':''}>${esc(a.text||'')}</textarea><p id="ex-wordcount">${countWords(a.text)} сөз · нысана ${esc(w.words)}</p><p>Мәтінге автоматты балл қойылмайды. Мұғалімге арналған есепке кіреді.</p>${cloudFeedback(spec.id,a.text)}</section>`;}
 body+=`<div class="tools-row">${a.submitted?'<button class="btn" data-action="report">Есепті жүктеу</button>':`<button class="btn" data-action="submit-exercise" data-id="${spec.id}" data-kind="${kind}">Жауаптарды жіберу</button>`}${link('/'+route,'Тізімге оралу','btn light')}</div>`;
 shell(head(spec.title,a.submitted?'Нәтиже мен түсіндірмелер':'Кілтті көрмей орында')+body,isMock?'Нұсқалар':'Оқылым');
}
function handleLearningClick(act,el){const code=el.dataset.code;
 if(act==='start-retest'){const r=state.retests[code]||{attempts:[]};if(!window.RETESTS[code]||r.draft||practiceCorrect(code)<3||r.attempts.length&&reviewDue(code)>Date.now())return true;r.draft={form:r.attempts.length?1-r.attempts.at(-1).form:0,values:{},at:Date.now()};state.retests[code]=r;save();retestPage(code);return true;}
 if(act==='submit-retest'){const r=state.retests[code],a=r?.draft;if(!a)return true;if(window.RETESTS[code][a.form].some((q,i)=>!a.values[i]?.trim())){toast('Үш сұрақтың бәріне жауап бер немесе ? қой.');return true;}a.at=Date.now();r.attempts.push(a);r.attempts=r.attempts.slice(-20);delete r.draft;save();retestPage(code);return true;}
 if(act==='start-exercise'){const spec=[...window.READING,...window.MOCKS].find(x=>x.id===el.dataset.id);if(!spec||state.exercises[spec.id])return true;state.exercises[spec.id]={answers:{},text:'',plan:'',started:Date.now(),finished:null,submitted:false,exposed:(spec.reading||[]).filter(id=>state.readingSeen[id]!==undefined)};for(const id of spec.reading||[spec.id])state.readingSeen[id]=Date.now();save();exercisePage(el.dataset.kind,spec);return true;}
 if(act==='submit-exercise'){const spec=[...window.READING,...window.MOCKS].find(x=>x.id===el.dataset.id),a=state.exercises[el.dataset.id];if(!spec||!a||a.submitted)return true;const r=exerciseScore(spec,a),short=spec.writing&&countWords(a.text)<Number(spec.writing.words.split('–')[0]);const submit=()=>{a.submitted=true;a.finished=Date.now();save();exercisePage(el.dataset.kind,spec);};if(r.entered<r.total||short)confirmAction('Толық емес жұмысты жіберу',`${r.total-r.entered} қысқа жауап бос.${short?' Writing ұсынылған көлемге жетпеген.':''} Нәтиже толық емес деп белгіленеді. Кілт ашылған соң жауаптар өзгермейді.`,submit,'Жіберу');else submit();return true;}
 return false;
}
function handleLearningInput(el){
 if(el.dataset.retest){const a=state.retests[el.dataset.retest]?.draft,i=Number(el.dataset.index);if(a&&Number.isInteger(i)&&i>=0&&i<3){a.values[i]=String(el.value).slice(0,2000);save();}return true;}
 if(el.dataset.exercise){const a=state.exercises[el.dataset.exercise],i=Number(el.dataset.index);if(a&&!a.submitted&&Number.isInteger(i)&&i>=0&&i<40){a.answers[i]=String(el.value).slice(0,2000);save();}return true;}
 if(el.dataset.exerciseWrite){const a=state.exercises[el.dataset.exerciseWrite],field=el.dataset.field;if(a&&!a.submitted&&['text','plan'].includes(field)){a[field]=String(el.value).slice(0,field==='plan'?4000:20000);save();const node=document.getElementById('ex-wordcount');if(node&&field==='text')node.textContent=countWords(a.text)+' сөз';}return true;}
 return false;
}
