function historyItems(){const out=[];for(const f of D.families)for(const a of state.retests[f.code]?.attempts||[])out.push({kind:'retest',title:f.title,date:a.at,score:retScore(f.code,a),total:3,route:'/retest/'+f.code});for(const t of [...window.READING,...window.MOCKS]){const a=state.exercises[t.id];if(a?.submitted){const s=exerciseScore(t,a);out.push({kind:t.reading?'mock':'reading',title:t.title,date:a.finished||a.started,score:s.score,total:s.total,route:'/'+(t.reading?'mocks':'reading')+'/'+t.id});}}return out.sort((a,b)=>a.date-b.date);}
function historyChart(){const data=historyItems().filter(x=>chartFilter==='all'||x.kind===chartFilter).slice(-12);if(!data.length)return `<section class="card chart-card"><div class="card-head"><div><span class="module-label">УАҚЫТ БОЙЫНША ІЛГЕРІЛЕУ</span><h2>Нәтиже динамикасы</h2></div>${ic('chart')}</div>${emptyState('Алғашқы нүкте әлі алда','Қайта тексеруді немесе Reading тапсырмасын аяқтағанда, нақты нәтиже осы жерде пайда болады.','/path','Жолды ашу','chart')}</section>`;
 const width=640,height=200,left=40,top=18,plotW=570,plotH=145,points=data.map((x,i)=>({x:left+(data.length===1?plotW/2:i*plotW/(data.length-1)),y:top+plotH*(1-x.score/x.total),...x})),selected=points[Math.min(chartSelection<0?points.length-1:chartSelection,points.length-1)];
 return `<section class="card chart-card"><div class="card-head"><div><span class="module-label">УАҚЫТ БОЙЫНША ІЛГЕРІЛЕУ</span><h2>Нәтиже динамикасы</h2></div>${pill(data.length+' әрекет')}</div><div class="chart-filters" role="group" aria-label="Нәтиже түрі">${[['all','Барлығы'],['retest','Қайта тексеру'],['reading','Оқылым'],['mock','Нұсқалар']].map(([v,t])=>`<button class="chip ${chartFilter===v?'active':''}" data-action="chart-filter" data-value="${v}" aria-pressed="${chartFilter===v}">${t}</button>`).join('')}</div><div class="chart-detail"><strong>${esc(selected.title)}</strong><span>${selected.score}/${selected.total} · ${esc(new Date(selected.date).toLocaleDateString('kk-KZ',{timeZone:'Asia/Almaty'}))}</span></div><svg class="history-chart" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="history-chart-title"><title id="history-chart-title">Таңдалған тапсырмалардағы дұрыс жауаптардың үлесі. Бұл CEFR немесе олимпиадаға дайындық пайызы емес.</title>${[0,50,100].map(n=>`<line x1="${left}" y1="${top+plotH*(1-n/100)}" x2="610" y2="${top+plotH*(1-n/100)}" class="chart-grid"/><text x="3" y="${top+plotH*(1-n/100)+4}" class="chart-label">${n}%</text>`).join('')}<polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" class="chart-line"/>${points.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="${p===selected?6:4}" class="chart-point ${p===selected?'selected':''}"><title>${esc(p.title)}: ${p.score}/${p.total}</title></circle>`).join('')}</svg><div class="chart-controls" aria-label="График нүктелері">${points.map((p,i)=>`<button class="chart-point-button ${p===selected?'selected':''}" data-action="chart-select" data-index="${i}" aria-pressed="${p===selected}" aria-label="${esc(p.title)}: ${p.score}/${p.total}">${i+1}</button>`).join('')}</div><p class="note">Әр тапсырманың күрделілігі әртүрлі. Графикті бірдей деңгейдегі емтихан өсімі немесе дайындық пайызы деп қабылдама.</p></section>`;
}
function dashboard(){const s=summary(),next=nextRecommendation(),practice=LES.reduce((n,l)=>n+practiceCorrect(l.code),0),passed=D.families.filter(f=>currentProgress(f.code).passed).length,recent=historyItems().slice(-3).reverse(),name=CLOUD?.profile?.display_name?.split(' ')[0];
 shell(head(name?'Қайта келгеніңе қуаныштымыз, '+name+'!':'Жаңа жетістігің осы жерден басталады.','Ағылшын тіліңді жетілдіруге дайынсың ба?','<div class="status-pills">'+pill(diagnosticStatus().label,diagnosticStatus().tone)+pill(CLOUD?'Жеке кабинет':'Жергілікті дайындық',CLOUD?'good':'neutral')+'</div>')+`<section class="dashboard-hero"><div><span class="eyebrow">КЕЛЕСІ ОҚУ ҚАДАМЫҢ</span><h2>${esc(next.title)}</h2><p>${esc(next.reason)}</p>${link(s.entered?next.route:'/diagnostic',next.button,'btn white')}</div><div class="dashboard-hero-art" aria-hidden="true">${ic('cap')}<span class="hero-orbit one"></span><span class="hero-orbit two"></span><small>БІЛІМ.<br>СЕНІМ.<br>МҮМКІНДІК.</small></div></section><div class="metric-grid">${metric('Диагностика',s.entered+'/88','Жауап берілген тапсырмалар','test')}${metric('Жаңа тексерулер',passed+'/21','Сәтті өткен тақырыптар','checkcircle')}${metric('Практика',practice+'/126','Дұрыс орындалған жаттығулар','book')}${metric('Ағылшын тілі деңгейі','Әлі бағаланбаған','CEFR үшін кешенді бағалау қажет','cap')}</div><div class="dashboard-columns"><div>${historyChart()}<section class="card spaced"><div class="card-head"><div><span class="module-label">ТІЛДІК ДАҒДЫЛАР КАРТАСЫ</span><h2>Қазір неге назар аударамыз?</h2></div>${link('/path','Оқу жолы','text-link')}</div>${done()?`<div class="focus-topics">${[...D.families].sort((a,b)=>priority(a)-priority(b)).slice(0,3).map(f=>`<a href="#/learn/${f.code}"><span class="icon-square">${ic('book')}</span><div><strong>${esc(labelKk(f.title))}</strong><small>${esc(currentProgress(f.code).name)}</small></div>${ic('chevron')}</a>`).join('')}</div>`:emptyState('Алдымен бастапқы дәлелді жинаймыз','Күшті және әлсіз үлгілер төрт диагностикалық блок жіберілгеннен кейін ашылады.','/diagnostic','Диагностикаға өту','test')}</section></div><aside><section class="card milestone-card"><span class="gold-icon">${ic('target')}</span><span class="module-label">КЕЛЕСІ МАҚСАТ</span><h2>${!done()?'Бастапқы картаңды жаса':passed<1?'Алғашқы жаңа тексеру':'Тұрақты қайталауды жалғастыр'}</h2><p>${!done()?s.entered+'/88 жауап сақталған. Әр жауап нақты бір дағдыны көрсетеді.':'Бірінші нәтиже мен кейінгі тексеру бөлек сақталады.'}</p><div class="track" role="progressbar" aria-label="Диагностикалық жауаптар" aria-valuemin="0" aria-valuemax="88" aria-valuenow="${s.entered}"><span style="width:${s.entered/88*100}%"></span></div>${link('/achievements','Жетістіктерді қарау','text-link')}</section><section class="card spaced"><div class="card-head"><h2>Соңғы әрекеттер</h2>${ic('clock')}</div>${recent.length?recent.map(a=>`<a class="activity-row" href="#${a.route}"><span class="activity-dot"></span><div><strong>${esc(a.title)}</strong><small>${a.score}/${a.total} · ${esc(new Date(a.date).toLocaleDateString('kk-KZ',{timeZone:'Asia/Almaty'}))}</small></div>${ic('chevron')}</a>`).join(''):'<p class="note">Алғашқы аяқталған тексеру осында көрсетіледі.</p>'}</section><section class="readiness-note">${ic('shield')}<p><strong>Олимпиадаға дайындық</strong><br>Әзірге жеке қорытынды жоқ. Бір пайыз толық дайындықты өлшемейді.</p></section></aside></div>`,'Басты бет');}
function learningPath(){const sorted=[...D.families].sort((a,b)=>priority(a)-priority(b));shell(head('Менің оқу жолым','Бастапқы дәлел → мақсатты жаттығу → жаңа тексеру → аралық қайталау.',link('/diagnostic','Бастапқы диагностика','btn light'))+`<div class="path-intro"><div class="path-intro-number">01<span>БАСТАПҚЫ ДАЙЫНДЫҒЫҢ</span></div><div><h2>Келесі қадам кездейсоқ таңдалмайды.</h2><p>Алдымен жауаптарыңдағы үлгілерге қараймыз. Кейін практика мен жаңа тексерудің дәлелін бөлек жинаймыз.</p></div></div><div id="assignment-slot">${assignmentSummary()}</div><section class="path-list">${sorted.map((f,i)=>{const p=currentProgress(f.code),n=practiceCorrect(f.code),r=topicResult(f);return `<article class="path-item"><div class="path-index ${p.passed?'earned':''}">${p.passed?ic('check'):String(i+1).padStart(2,'0')}</div><div class="path-item-body"><div class="flex-between"><span class="module-label">${f.code} · ${f.code[0]==='G'?'ГРАММАТИКА':'ТІЛДІ ҚОЛДАНУ'}</span>${pill(p.name,p.tone)}</div><h2>${esc(labelKk(f.title))}</h2><p>Бастапқы: ${esc(r.name)}${done()?' · '+r.score+'/'+r.total:''}</p><div class="path-mini-steps"><span class="${n>=3?'complete':''}">${ic('book')} Практика ${n}/6</span><span class="${p.passed?'complete':''}">${ic('test')} Жаңа тексеру</span><span>${ic('repeat')} Аралық қайталау</span></div></div>${link(p.route,p.button,'btn light small')}</article>`;}).join('')}</section>`,'Менің оқу жолым');loadAssignmentSlot();}
function awards(){const answered=allQ.filter(attempted).length,p=LES.reduce((n,l)=>n+practiceCorrect(l.code),0),ret=D.families.filter(f=>currentProgress(f.code).passed).length,read=window.READING.filter(t=>state.exercises[t.id]?.submitted&&exerciseScore(t,state.exercises[t.id]).entered===10).length,writes=[...D.writing,...writingTasks].filter(w=>countWords((w.id.startsWith('W')?state.writing:state.drafts)[w.id]?.text)>=Number(w.words.split('–')[0])).length;return [{id:'first-step',icon:'path',title:'Алғашқы қадам',text:'Диагностикада алғашқы жауапты сақта.',value:answered?1:0,total:1},{id:'practice',icon:'book',title:'Тілдік үлгілерді зерттеуші',text:'Үш жаттығуды дұрыс орында.',value:Math.min(p,3),total:3},{id:'new-evidence',icon:'shield',title:'Жаңа нәтиже',text:'Бір жаңа тексеруде 3/3 нәтиже ал.',value:ret?1:0,total:1},{id:'reader',icon:'eye',title:'Зейінді оқырман',text:'Бір Reading мәтініндегі 10 сұраққа жауап беріп жібер.',value:read?1:0,total:1},{id:'writer',icon:'pen',title:'Өзіндік ой',text:'Ұсынылған көлемге жететін бір мәтін жаз. Бұл сапа бағасы емес.',value:writes?1:0,total:1},{id:'map',icon:'trophy',title:'Айқын оқу картасы',text:'88 диагностикалық жауап пен екі жеткілікті көлемдегі жазба жұмысты жібер.',value:done()&&answered===88&&D.writing.every(w=>countWords(state.writing[w.id]?.text)>=Number(w.words.split('–')[0]))?1:0,total:1}];}
let previousAwardIds=null;
function checkAwards(){const a=awards(),ids=new Set(a.filter(x=>x.value>=x.total).map(x=>x.id));if(previousAwardIds&&storageOK){const earned=a.find(x=>ids.has(x.id)&&!previousAwardIds.has(x.id));if(earned)toast('Жаңа жетістік: '+earned.title+'!');}previousAwardIds=ids;}
function achievements(){const list=awards(),earned=list.filter(x=>x.value>=x.total).length;shell(head('Жетістіктер','Нақты орындалған қадамдарға негізделген шағын жетістіктер.',pill(earned+'/'+list.length+' жетістік','good'))+`<div class="achievement-intro"><span>${ic('trophy')}</span><div><h2>Жетістік еңбектен басталады.</h2><p>Әр белгі нақты әрекетті көрсетеді. Олар CEFR сертификаты немесе олимпиада нәтижесінің болжамы емес.</p></div></div><div class="achievement-grid">${list.map(a=>`<article class="achievement-card ${a.value>=a.total?'earned':'locked'}"><span class="award-symbol">${ic(a.icon)}</span>${pill(a.value>=a.total?'Иеленді':'Орындалуда',a.value>=a.total?'good':'neutral')}<h2>${esc(a.title)}</h2><p>${esc(a.text)}</p><div class="track" role="progressbar" aria-label="${esc(a.title)}" aria-valuemin="0" aria-valuemax="${a.total}" aria-valuenow="${a.value}"><span style="width:${a.value/a.total*100}%"></span></div><small>${a.value}/${a.total}</small></article>`).join('')}</div>`,'Жетістіктер');}
function progressPage(){const s=summary(),h=historyItems();shell(head('Менің ілгерілеуім','Жаттығудан кейін не өзгергенін нақты дәлелдермен қара.',link('/results','Толық диагностикалық есеп','btn light'))+`<div class="metric-grid">${metric('Аяқталған тексеру',h.length,'Reading, қайта тексеру және нұсқалар','chart')}${metric('Жаңа дәлел',D.families.filter(f=>currentProgress(f.code).passed).length+'/21','Сәтті жаңа тексерулер','shield')}${metric('Диагностика',s.entered+'/88','Жауап берілген тармақтар','test')}${metric('Дайындық','Бағаланбаған','Кешенді қорытынды әлі жасалмаған','target')}</div>${historyChart()}<section class="card spaced"><div class="card-head"><h2>Тақырыптар бойынша бастапқы дәлел</h2>${ic('book')}</div>${done()?`<div class="skill-bars">${s.topics.map(x=>`<a href="#/learn/${x.f.code}" class="skill-bar"><div><strong>${esc(labelKk(x.f.title))}</strong><span>${x.score}/${x.total} · ${esc(x.name)}</span></div><div class="track"><span style="width:${x.score/x.total*100}%"></span></div></a>`).join('')}</div>`:emptyState('Карта әлі ашылған жоқ','Бастапқы нәтижені көрсету үшін төрт блок жіберілуі керек. Кілттер ерте ашылмайды.','/diagnostic','Тестті жалғастыру','test')}</section>`,'Менің ілгерілеуім');}
function readingHub(id){if(id&&id!=='use'){exerciseRoute('reading',id);return;}if(id==='use'){shell(head('Оқылым және тілді қолдану','Мәтіндегі мағына мен тілдік үлгіні бірге түсін.')+`<div class="tab-links"><a href="#/reading">Оқылым</a><a href="#/reading/use" aria-current="page">Тілді қолдану</a></div><div class="topics-grid">${D.families.filter(f=>f.code[0]==='V').map(topicCard).join('')}</div>`,'Оқылым және тілді қолдану');return;}exerciseRoute('reading');const main=document.getElementById('main');if(main)main.insertAdjacentHTML?.('afterbegin','<div class="tab-links"><a href="#/reading" aria-current="page">Оқылым</a><a href="#/reading/use">Тілді қолдану</a></div>');}
function diagnosticGroups(b){if(b===1||b===2){const source=D.items.slice(b===1?0:30,b===1?30:60);return Array.from({length:6},(_,i)=>source.slice(i*5,i*5+5));}if(b===3)return [D.items.slice(60,66),D.items.slice(66,69),D.items.slice(69,72),D.items.slice(72,75),D.items.slice(75,78),D.reading.slice(0,5),D.reading.slice(5)];return [[]];}
function questionPage(b,n){return Math.max(0,diagnosticGroups(b).findIndex(group=>group.some(q=>q.n===n)));}
function reviewPage(b){if(![1,2,3,4].includes(b)||b>1&&!state.completeBlocks.includes(b-1)){diagnostic();return;}const qs=blockQuestions(b),missing=qs.filter(q=>!attempted(q)).length,flagged=qs.filter(q=>state.flags[q.n]).length;shell(head('Жібермес бұрын тексер',b+' блок · жауаптарыңды және белгіленген сұрақтарды қайта қара.',link('/diagnostic/'+b+'/0','Тестке оралу','btn light'))+`<div class="review-summary">${metric('Жауаптар',qs.length-missing+'/'+qs.length,'Жібермес бұрын қарап шық','test')}${metric('Белгіленген',flagged,'Қайта қарауды қалаған сұрақтар','flag')}</div><div class="review-list">${b===4?D.writing.map(w=>`<a href="#/diagnostic/4/0"><strong>${w.id} · ${esc(labelKk(w.title))}</strong><span>${countWords(state.writing[w.id]?.text)} сөз / ${esc(w.words)}</span>${ic('chevron')}</a>`).join(''):qs.map(q=>`<a href="#/diagnostic/${b}/${questionPage(b,q.n)}"><span class="review-number ${state.flags[q.n]?'flagged':''}">${q.n}</span><div><strong>${esc(q.subskill||q.topic||'Тапсырма')}</strong><small>${esc(answer(q.n).value||'Жауап жоқ')} · ${esc(answer(q.n).confidence||'Сенім белгісі жоқ')}</small></div>${state.flags[q.n]?ic('flag'):ic('chevron')}</a>`).join('')}</div><div class="test-actions">${link('/diagnostic/'+b+'/0','Қайта қарау','btn light')}<button class="btn" data-action="finish-block" data-block="${b}">Жауаптарды жіберу ${ic('check')}</button></div><p class="note">Бос жауап толық меңгеру дәлелі болып есептелмейді. Кілт барлық блок жіберілгеннен кейін ашылады.</p>`,'Жауаптарды тексеру');}
function diagnosticModeControls(){const locked=allQ.some(attempted)||Object.keys(state.timer.sessions).length>0||state.completeBlocks.length>0;return `<div class="mode-choice"><div><strong>Орындау режимін таңда</strong><p>${locked?'Тест басталғандықтан, осы әрекеттің режимі сақталады.':'Бастапқы диагностиканы уақытпен немесе уақытсыз орындай аласың.'}</p></div><div role="group" aria-label="Диагностика режимі">${[['timed','clock','Уақытпен · 4 × 40 мин'],['untimed','book','Уақытсыз · өз қарқыныңмен']].map(([v,i,t])=>`<button class="chip ${state.diagnosticMode===v?'active':''}" data-action="diagnostic-mode" data-value="${v}" aria-pressed="${state.diagnosticMode===v}" ${locked?'disabled':''}>${ic(i)} ${t}</button>`).join('')}</div></div>`;}
function teacherOverview(){const records=cloudRoster||[],stats=records.map(r=>{try{return withStudent(r,()=>({entered:summary().entered,works:[...D.writing,...writingTasks].filter(w=>(w.id.startsWith('W')?state.writing:state.drafts)[w.id]?.text?.trim()).length,complete:done()}));}catch{return {entered:0,works:0,complete:false};}});return `<div class="teacher-overview"><span class="module-label">МҰҒАЛІМНІҢ ЖҰМЫС КЕҢІСТІГІ</span><h2>Әр оқушының ілгерілеуі назарда.</h2><p>Нәтижелер, нақты қателер және мәтінге байланған кері байланыс — бір жұмыс кеңістігінде.</p></div><div class="metric-grid">${metric('Оқушылар',records.length,'Сізге бекітілген тіркелгілер','teacher')}${metric('Басталған диагностика',stats.filter(s=>s.entered>0).length,'Кемінде бір жауап сақталған','test')}${metric('Жіберілген диагностика',stats.filter(s=>s.complete).length,'Төрт блогы жіберілген','checkcircle')}${metric('Жазба жұмыстар',stats.reduce((n,s)=>n+s.works,0),'W1–W2 және Writing Studio мәтіндері','pen')}</div><div class="toolbar"><label class="search-field">${ic('search')}<input class="search" id="teacher-search" type="search" value="${esc(teacherSearch)}" placeholder="Оқушыны аты не логині бойынша іздеу" aria-label="Оқушыны іздеу"></label></div>`;}
function handleDesignAction(act,el){
 if(act==='theme-toggle'){window.QAISAR_THEME?.toggle();render();return true;}
 if(act==='workspace-menu'){workspaceMenu=!workspaceMenu;render();return true;}
 if(act==='sample-answer'){const correct=el.dataset.value==='has',out=document.getElementById('sample-feedback');out.textContent=correct?'Дұрыс. She + has been + -ing бұрын басталып, әлі жалғасып жатқан әрекетті білдіреді.':'She есімдігімен has қолданылады: She has been learning English for two years.';out.classList.toggle('correct',correct);return true;}
 if(act==='chart-filter'){chartFilter=el.dataset.value;chartSelection=-1;location.hash==='#/home'?dashboard():progressPage();return true;}
 if(act==='chart-select'){chartSelection=Number(el.dataset.index);location.hash==='#/home'?dashboard():progressPage();return true;}
 if(act==='flag-question'){const n=Number(el.dataset.q);state.flags[n]=!state.flags[n];save();const parts=location.hash.split('/');diagPage(Number(parts[2]),Number(parts[3]||0));return true;}
 if(act==='diagnostic-mode'){if(allQ.some(attempted)||Object.keys(state.timer.sessions).length||state.completeBlocks.length)return true;state.diagnosticMode=el.dataset.value==='untimed'?'untimed':'timed';save();diagnostic();return true;}
 return false;
}

let assignmentLoaded=false,assignmentLoading=false,assignmentError='';
function assignmentTarget(a){if(a.kind==='diagnostic')return '/diagnostic';if(a.kind==='lesson'&&D.families.some(f=>f.code===a.target))return '/learn/'+a.target;if(a.kind==='writing'&&writingTasks.some(w=>w.id===a.target))return '/writing/'+a.target;if(a.kind==='writing'&&['W1','W2'].includes(a.target))return '/diagnostic/4/0';return null;}
function assignmentSummary(){if(!CLOUD)return `<section class="card spaced"><div class="card-head"><h2>Мұғалімнің тапсырмалары</h2>${ic('teacher')}</div><p class="note">Онлайн кабинет қосылғанда, мұғалімнің жеке тапсырмалары осында көрінеді. Қазір өз бетіңше дайындық қолжетімді.</p>${link('/account','Кабинет жайлы','text-link')}</section>`;if(assignmentLoading)return '<div class="skeleton-card spaced" role="status" aria-label="Тапсырмалар жүктелуде"><span class="skeleton"></span><span class="skeleton"></span></div>';if(assignmentError)return `<div class="banner">${esc(assignmentError)}<button class="btn light small" data-action="assignments-refresh">Қайта жүктеу</button></div>`;if(CLOUD.assignmentSupport===false)return '<div class="banner">Мұғалімнің тапсырмалар қызметі әлі қосылмаған. Негізгі дайындықты жалғастыра аласың.</div>';const list=CLOUD.assignments||[];return `<section class="card spaced"><div class="card-head"><h2>Мұғалімнің тапсырмалары</h2>${pill(list.length+' тапсырма')}</div>${list.length?list.map(a=>`<a class="activity-row" href="#/assignments/${esc(a.id)}"><span class="icon-square">${ic(a.kind==='writing'?'pen':'file')}</span><div><strong>${esc(a.title)}</strong><small>${a.due_at?'Мерзімі: '+esc(new Date(a.due_at).toLocaleDateString('kk-KZ',{timeZone:'Asia/Almaty'})):'Мерзім қойылмаған'} · ${CLOUD.submissions?.find(s=>s.assignment_id===a.id)?.completed?'оқушы орындадым деп белгіледі':'орындалуда'}</small></div>${ic('chevron')}</a>`).join(''):'<p class="note">Әзірге жеке тапсырма жоқ. Өз оқу жолыңмен жалғастыр.</p>'}</section>`;}
function loadAssignmentSlot(){if(!CLOUD?.loadAssignments||assignmentLoaded||assignmentLoading)return;assignmentLoading=true;CLOUD.loadAssignments().then(()=>{assignmentLoaded=true;assignmentLoading=false;assignmentError='';if(location.hash.startsWith('#/assignments/'))assignmentPage(location.hash.split('/')[2]);else if(location.hash==='#/teacher/assignments')teacherAssignments();else if(location.hash==='#/path'){const slot=document.getElementById('assignment-slot');if(slot)slot.innerHTML=assignmentSummary();}}).catch(e=>{assignmentLoading=false;assignmentError=e.message;if(location.hash.startsWith('#/assignments/'))assignmentPage(location.hash.split('/')[2]);else if(location.hash==='#/teacher/assignments')teacherAssignments();else{const slot=document.getElementById('assignment-slot');if(slot)slot.innerHTML=assignmentSummary();}});}
function assignmentPage(id){if(!CLOUD||isCloudTeacher()){learningPath();return;}const a=CLOUD.assignments?.find(a=>a.id===id);if(!assignmentLoaded){shell(head('Мұғалімнің тапсырмасы','Жеке кабинеттегі тапсырма.')+`<div id="assignment-slot">${assignmentSummary()}</div>`,'Assignment');loadAssignmentSlot();return;}if(!a){shell(head('Тапсырма табылмады','Бұл тапсырма сізге қолжетімді емес немесе мұғалім оны архивке жіберген.')+link('/path','Оқу жолына оралу'),'Assignment');return;}const s=CLOUD.submissions?.find(s=>s.assignment_id===id),text=state.assignmentDrafts[id]??s?.response_text??'',target=assignmentTarget(a);shell(head(a.title,'Мұғалімнің жеке тапсырмасы',link('/path','Оқу жолына','btn light'))+`<section class="card"><div class="flex-between">${pill(a.kind)}<span class="note">${a.due_at?'Мерзімі: '+esc(new Date(a.due_at).toLocaleDateString('kk-KZ',{timeZone:'Asia/Almaty'})):'Мерзім қойылмаған'}</span></div><div class="teacher-text">${esc(a.instructions||'Мұғалім қосымша нұсқау бермеген.')}</div>${target?link(target,'Оқу материалын ашу'):''}<label class="section-mark spaced" for="assignment-response">Жауап немесе орындау туралы жазба</label><textarea class="writing-area spaced" id="assignment-response" data-assignment-draft="${esc(id)}" maxlength="20000">${esc(text)}</textarea><div class="tools-row"><button class="btn light" data-action="assignment-submit" data-id="${esc(id)}" data-completed="false">Жауапты серверге сақтау</button><button class="btn" data-action="assignment-submit" data-id="${esc(id)}" data-completed="true">Орындадым деп белгілеу</button></div><p class="note">Орындау белгісін оқушы өзі қояды. Мұғалім нақты жауаптарды және дайындық нәтижелерін бөлек талдайды.</p>${s?pill('Серверге сақталған','good'):''}</section>`,'Assignment');}
function teacherAssignments(){if(!isCloudTeacher())return;if(!cloudRoster&&!cloudLoading&&!cloudError){teacherCloud();return;}shell(head('Тапсырмалар мен ұсыныстар','Диагностика тағайында, жеке тапсырма жаса және нақты келесі қадамды ұсын.',link('/teacher','Оқушыларға оралу','btn light'))+`${cloudError?'<div class="banner">'+esc(cloudError)+'</div>':''}${CLOUD.assignmentSupport===false?'<div class="banner">Тапсырмалар қызметі серверде әлі қосылмаған. Қосылғаннан кейін осы жерде тапсырма бере аласыз.</div>':`<section class="card"><h2>Жаңа тапсырма</h2><div class="assignment-form spaced"><label>Оқушы<select id="assign-student"><option value="">Таңдаңыз</option>${(cloudRoster||[]).map(r=>`<option value="${esc(r.profile.id)}" ${selectedStudent===r.profile.id?'selected':''}>${esc(r.profile.display_name)}</option>`).join('')}</select></label><label>Түрі<select id="assign-kind"><option value="diagnostic">Диагностикалық тест</option><option value="lesson">Тақырып / жеке ұсыныс</option><option value="writing">Жазылым</option><option value="custom">Авторлық тапсырма</option></select></label><label class="full">Атауы<input id="assign-title" class="answer-input" maxlength="160" value="Бастапқы диагностиканы орындау"></label><label>Оқу материалы<select id="assign-target"><option value="">Диагностика / еркін тапсырма</option>${D.families.map(f=>`<option value="${f.code}">${esc(labelKk(f.title))}</option>`).join('')}${writingTasks.map(w=>`<option value="${w.id}">${w.id} · ${w.title}</option>`).join('')}</select></label><label>Мерзімі · Алматы уақыты<input type="date" id="assign-due" class="answer-input"></label><label class="full">Нұсқау немесе жеке ұсыныс<textarea class="writing-area plan-area" id="assign-instructions" maxlength="6000" placeholder="Мақсаты, орындалу тәртібі және неге назар аудару керек…"></textarea></label></div><button class="btn spaced" data-action="assignment-create" ${CLOUD.assignmentSupport===true?'':'disabled'}>${ic('plus')} Тапсырманы серверге сақтау</button></section>`}<section class="card spaced"><div class="card-head"><h2>Берілген тапсырмалар</h2>${pill((CLOUD.assignments||[]).length+' тапсырма')}</div>${(CLOUD.assignments||[]).map(a=>{const s=CLOUD.submissions?.find(s=>s.assignment_id===a.id),p=cloudRoster?.find(r=>r.profile.id===a.student_id)?.profile;return `<article class="assignment-card card"><div class="assignment-title"><h3>${esc(a.title)}</h3>${pill(s?.completed?'Оқушы орындадым деп белгіледі':'Жауап күтілуде',s?.completed?'good':'neutral')}</div><p>${esc(p?.display_name||'Оқушы')} · ${esc(labelKk(a.kind))}</p><p>${esc(a.instructions)}</p>${s?`<div class="teacher-text">${esc(s.response_text||'Мәтіндік жауап жоқ.')}</div><p class="note">Сақталғаны: ${esc(new Date(s.updated_at).toLocaleString('kk-KZ',{timeZone:'Asia/Almaty'}))}</p>`:'<p class="note">Жауап әлі сақталмаған.</p>'}</article>`;}).join('')||'<p class="note">Әзірге тапсырма берілген жоқ.</p>'}</section>`,'Тапсырмалар');loadAssignmentSlot();}
async function assignmentAction(act,el){try{if(act==='assignments-refresh'){assignmentLoaded=false;assignmentError='';learningPath();return;}if(act==='assignment-create'){if(!isCloudTeacher())throw new Error('Мұғалімге ғана қолжетімді.');const value=id=>document.getElementById(id).value,kind=value('assign-kind'),target=value('assign-target'),student=value('assign-student'),title=value('assign-title').trim();if(!student||!title)throw new Error('Оқушыны және тапсырма атауын көрсетіңіз.');if(kind==='lesson'&&!D.families.some(f=>f.code===target)||kind==='writing'&&!writingTasks.some(w=>w.id===target))throw new Error('Тапсырма түріне сәйкес оқу материалын таңдаңыз.');const due=value('assign-due');el.disabled=true;await CLOUD.createAssignment({student_id:student,kind,title,target,instructions:value('assign-instructions'),due_at:due?new Date(due+'T23:59:59+05:00').toISOString():null});toast('Тапсырма серверге сақталды.');teacherAssignments();return;}if(act==='assignment-submit'){if(CLOUD?.profile?.role!=='student')return;const text=document.getElementById('assignment-response').value;el.disabled=true;await CLOUD.respondAssignment(el.dataset.id,text,el.dataset.completed==='true');toast('Жауап серверге сақталды.');assignmentPage(el.dataset.id);}}catch(e){toast(e.message||'Тапсырманы сақтау мүмкін емес.');}finally{el.disabled=false;}}

document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();document.getElementById('main')?.focus({preventScroll:false});return;}const el=e.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;
 if(handleDesignAction(act,el))return;
 if(act.startsWith('assignment')){assignmentAction(act,el);return;}
 if(act.startsWith('cloud-')){cloudClick(act,el);return;}
 if(handleLearningClick(act,el))return;
 if(act==='confidence'){const n=Number(el.dataset.q);state.answers[n]={...answer(n),confidence:el.dataset.value};save();el.parentElement.querySelectorAll('button').forEach(b=>{const on=b===el;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));});}
 if(act==='finish-block')finishBlock(Number(el.dataset.block));
 if(act==='timer'){const b=Number(el.dataset.block);if(state.timer.running&&state.timer.block===b)pauseTimer();else{pauseTimer();state.timer.block=b;state.timer.started=Date.now();state.timer.running=true;save();}const parts=location.hash.split('/');diagPage(b,Number(parts[3]||0));}
 if(act==='topic-filter'){filter=el.dataset.value;topics();}
 if(act==='check-practice'){const code=el.dataset.code,i=Number(el.dataset.index);state.training[code]??={};state.training[code][i]??={value:'',checked:false};if(!state.training[code][i].value.trim()){toast('Алдымен өз жауабыңды жаз.');return;}state.training[code][i].checked=true;save();const y=window.scrollY;learn(code);window.scrollTo(0,y);document.querySelector(`button[data-action="check-practice"][data-code="${code}"][data-index="${i}"]`)?.focus({preventScroll:true});}
 if(act==='flip'){flipped=true;reviewWords();}
 if(act==='word-rate'){const id=Number(el.dataset.id),known=el.dataset.known==='true',step=known?Math.min((state.words[id]?.step||0)+1,5):0,days=[0,1,3,7,14,30];state.words[id]={step,due:Date.now()+(known?days[step]*86400000:600000)};flipped=false;flashIndex=0;save();reviewWords();}
 if(act==='recovery'&&recoveryBackup)downloadFile(recoveryBackup,'application/json','English_Olympiad_previous_progress.json');
 if(act==='download')exportData();if(act==='report')exportData(true);if(act==='import')document.getElementById('import-file').click();
 if(act==='review-filter'){reviewFilter=el.dataset.value;teacher();}

 if(act==='reset')confirmAction('Нәтижелерді тазалау','Осы браузердегі жауаптар, мәтіндер және прогресс өшеді. Қажет болса, алдымен файлға жүктеп ал.',()=>{pauseTimer();if(!retainBackup())return;state=fresh();storageConflict=false;recoveryWarning=false;save();go('/home');toast('Прогресс тазаланды. Бұрынғы нұсқаның көшірмесі сақталды.');},'Тазалау');
});
document.addEventListener('input',e=>{const el=e.target;
 if(el.dataset.cloudFeedback&&isCloudTeacher()){const d=reviewDrafts[el.dataset.cloudFeedback];if(d){d.feedback=el.value;d.dirty=true;}return;}
 if(el.id==='teacher-search'){teacherSearch=el.value;const pos=el.selectionStart;teacherCloud();const n=document.getElementById('teacher-search');n?.focus();try{n?.setSelectionRange(pos,pos);}catch{}return;}
 if(el.dataset.assignmentDraft){state.assignmentDrafts[el.dataset.assignmentDraft]=el.value;save();return;}
 if(handleLearningInput(el))return;
 if(el.dataset.answer){const n=Number(el.dataset.answer);if(answer(n).value!==el.value)delete state.manual[n];state.answers[n]={...answer(n),value:el.value};save();const dot=document.getElementById('dot-'+n);if(dot)dot.classList.toggle('done',el.value.trim().length>0);}
 if(el.dataset.practice){const code=el.dataset.practice,i=Number(el.dataset.index);state.training[code]??={};state.training[code][i]={value:el.value,checked:false};el.closest('.practice-item')?.querySelector('.feedback')?.remove();save();}
 if(el.dataset.write){const group=el.dataset.group,id=el.dataset.write;state[group][id]??={text:'',plan:''};if(el.dataset.field==='text'&&state[group][id].text!==el.value&&state.grades[id]){state.grades[id]={...state.grades[id],content:null,organization:null,language:null,stale:true};const banner=document.getElementById('grade-status-'+id);if(banner)banner.textContent='Мәтін өзгерді — қайта бағалау қажет.';}state[group][id][el.dataset.field]=el.value;save();if(el.dataset.field==='text'){const w=[...D.writing,...writingTasks].find(w=>w.id===id);document.getElementById('wordcount-'+id).textContent=countWords(el.value)+' сөз · нысана '+w.words;}}

 if(el.id==='topic-search'){topicSearch=el.value;const start=el.selectionStart;topics();const n=document.getElementById('topic-search');n.focus();try{n.setSelectionRange(start,start);}catch{}}
 if(el.id==='word-search'){wordSearch=el.value;const start=el.selectionStart;vocab();const n=document.getElementById('word-search');n.focus();try{n.setSelectionRange(start,start);}catch{}}
});
document.addEventListener('keydown',e=>{if(!workspaceMenu)return;if(e.key==='Escape'){workspaceMenu=false;render();document.querySelector('.menu-button')?.focus();return;}if(e.key==='Tab'){const els=Array.from(document.querySelectorAll('.sidebar a,.sidebar button'));if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.cloudGrade&&isCloudTeacher()){const d=reviewDrafts[el.dataset.cloudGrade];if(d&&['content','organization','language'].includes(el.dataset.field)){d[el.dataset.field]=el.value===''?null:Number(el.value);d.dirty=true;}return;}if(el.id==='word-group'){wordFilter=el.value;vocab();}if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();}});
document.getElementById('import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2*1024*1024){toast('Файл тым үлкен. Платформадан алынған JSON файлын таңдаңыз.');return;}try{const incoming=sanitize(JSON.parse(await file.text()));chooseImport(incoming);}catch(err){toast('Файлды ашу мүмкін емес: '+(err.message||'пішімі сәйкес емес.'));}});
window.addEventListener('hashchange',()=>{workspaceMenu=false;render();});window.addEventListener('pagehide',()=>pauseTimer());document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseTimer();const b=document.getElementById('timer-button');if(b)b.innerHTML=ic('play')+'Уақытты қосу';}});
setInterval(()=>{if(!state.timer.running)return;const el=document.getElementById('timer-display');if(el){const t=2400-elapsedTime(state.timer.block);el.textContent=formatTime(t);el.classList.toggle('time-over',t<0);}if(state.timer.running&&Math.floor(elapsedTime(state.timer.block))%15===0){const b=state.timer.block;state.timer.elapsed[b]=elapsedTime(b);state.timer.started=Date.now();save();}},1000);
